INSERT INTO "public"."cards" (deck_id, name, description, type, category, usage_examples, translations) VALUES
('00000000-0000-0000-0000-000000000001', 'The Reluctant Hero', 'A character who is called to adventure but initially resists their destiny, only to rise when needed most.', 'story', 'protagonist', 'Use when introducing a main character who doubts themselves or when showing character growth.', '{"en":{"name":"The Reluctant Hero","description":"A character who is called to adventure but initially resists their destiny, only to rise when needed most.","usage_examples":"Use when introducing a main character who doubts themselves or when showing character growth."},"ru":{"name":"[RU] The Reluctant Hero","description":"[RU] A character who is called to adventure but initially resists their destiny, only to rise when needed most.","usage_examples":"[RU] Use when introducing a main character who doubts themselves or when showing character growth."},"ua":{"name":"[UA] The Reluctant Hero","description":"[UA] A character who is called to adventure but initially resists their destiny, only to rise when needed most.","usage_examples":"[UA] Use when introducing a main character who doubts themselves or when showing character growth."}}'),
('00000000-0000-0000-0000-000000000001', 'The Chosen One', 'A person marked by prophecy or fate to accomplish a great deed, bearing the weight of destiny.', 'story', 'protagonist', 'Play when revealing a character''s special purpose or when prophecy becomes relevant.', '{"en":{"name":"The Chosen One","description":"A person marked by prophecy or fate to accomplish a great deed, bearing the weight of destiny.","usage_examples":"Play when revealing a character''s special purpose or when prophecy becomes relevant."},"ru":{"name":"[RU] The Chosen One","description":"[RU] A person marked by prophecy or fate to accomplish a great deed, bearing the weight of destiny.","usage_examples":"[RU] Play when revealing a character''s special purpose or when prophecy becomes relevant."},"ua":{"name":"[UA] The Chosen One","description":"[UA] A person marked by prophecy or fate to accomplish a great deed, bearing the weight of destiny.","usage_examples":"[UA] Play when revealing a character''s special purpose or when prophecy becomes relevant."}}'),
('00000000-0000-0000-0000-000000000001', 'The Orphaned Child', 'A young soul without family, seeking belonging and purpose in a harsh world.', 'story', 'protagonist', 'Introduce to create sympathy or when exploring themes of family and identity.', '{"en":{"name":"The Orphaned Child","description":"A young soul without family, seeking belonging and purpose in a harsh world.","usage_examples":"Introduce to create sympathy or when exploring themes of family and identity."},"ru":{"name":"[RU] The Orphaned Child","description":"[RU] A young soul without family, seeking belonging and purpose in a harsh world.","usage_examples":"[RU] Introduce to create sympathy or when exploring themes of family and identity."},"ua":{"name":"[UA] The Orphaned Child","description":"[UA] A young soul without family, seeking belonging and purpose in a harsh world.","usage_examples":"[UA] Introduce to create sympathy or when exploring themes of family and identity."}}'),
('00000000-0000-0000-0000-000000000001', 'The Exiled Prince', 'Royalty cast out from their kingdom, seeking redemption or revenge.', 'story', 'protagonist', 'Use when introducing political intrigue or a character with a claim to power.', '{"en":{"name":"The Exiled Prince","description":"Royalty cast out from their kingdom, seeking redemption or revenge.","usage_examples":"Use when introducing political intrigue or a character with a claim to power."},"ru":{"name":"[RU] The Exiled Prince","description":"[RU] Royalty cast out from their kingdom, seeking redemption or revenge.","usage_examples":"[RU] Use when introducing political intrigue or a character with a claim to power."},"ua":{"name":"[UA] The Exiled Prince","description":"[UA] Royalty cast out from their kingdom, seeking redemption or revenge.","usage_examples":"[UA] Use when introducing political intrigue or a character with a claim to power."}}'),
('00000000-0000-0000-0000-000000000001', 'The Brave Farmhand', 'A simple worker with extraordinary courage hidden beneath an ordinary exterior.', 'story', 'protagonist', 'Play to show that heroism can come from anywhere, not just nobility.', '{"en":{"name":"The Brave Farmhand","description":"A simple worker with extraordinary courage hidden beneath an ordinary exterior.","usage_examples":"Play to show that heroism can come from anywhere, not just nobility."},"ru":{"name":"[RU] The Brave Farmhand","description":"[RU] A simple worker with extraordinary courage hidden beneath an ordinary exterior.","usage_examples":"[RU] Play to show that heroism can come from anywhere, not just nobility."},"ua":{"name":"[UA] The Brave Farmhand","description":"[UA] A simple worker with extraordinary courage hidden beneath an ordinary exterior.","usage_examples":"[UA] Play to show that heroism can come from anywhere, not just nobility."}}'),
('00000000-0000-0000-0000-000000000001', 'The Cursed Wanderer', 'A traveler bearing a terrible curse, seeking either a cure or acceptance.', 'story', 'protagonist', 'Introduce when adding mystery or when a character needs a dark secret.', '{"en":{"name":"The Cursed Wanderer","description":"A traveler bearing a terrible curse, seeking either a cure or acceptance.","usage_examples":"Introduce when adding mystery or when a character needs a dark secret."},"ru":{"name":"[RU] The Cursed Wanderer","description":"[RU] A traveler bearing a terrible curse, seeking either a cure or acceptance.","usage_examples":"[RU] Introduce when adding mystery or when a character needs a dark secret."},"ua":{"name":"[UA] The Cursed Wanderer","description":"[UA] A traveler bearing a terrible curse, seeking either a cure or acceptance.","usage_examples":"[UA] Introduce when adding mystery or when a character needs a dark secret."}}'),
('00000000-0000-0000-0000-000000000001', 'The Silent Guardian', 'A protector who watches from the shadows, speaking rarely but acting decisively.', 'story', 'protagonist', 'Use for mysterious protector figures or when actions speak louder than words.', '{"en":{"name":"The Silent Guardian","description":"A protector who watches from the shadows, speaking rarely but acting decisively.","usage_examples":"Use for mysterious protector figures or when actions speak louder than words."},"ru":{"name":"[RU] The Silent Guardian","description":"[RU] A protector who watches from the shadows, speaking rarely but acting decisively.","usage_examples":"[RU] Use for mysterious protector figures or when actions speak louder than words."},"ua":{"name":"[UA] The Silent Guardian","description":"[UA] A protector who watches from the shadows, speaking rarely but acting decisively.","usage_examples":"[UA] Use for mysterious protector figures or when actions speak louder than words."}}'),
('00000000-0000-0000-0000-000000000001', 'The Clever Thief', 'A cunning rogue who steals not just treasures, but also hearts and secrets.', 'story', 'protagonist', 'Play when wit and stealth are needed, or to add moral complexity.', '{"en":{"name":"The Clever Thief","description":"A cunning rogue who steals not just treasures, but also hearts and secrets.","usage_examples":"Play when wit and stealth are needed, or to add moral complexity."},"ru":{"name":"[RU] The Clever Thief","description":"[RU] A cunning rogue who steals not just treasures, but also hearts and secrets.","usage_examples":"[RU] Play when wit and stealth are needed, or to add moral complexity."},"ua":{"name":"[UA] The Clever Thief","description":"[UA] A cunning rogue who steals not just treasures, but also hearts and secrets.","usage_examples":"[UA] Play when wit and stealth are needed, or to add moral complexity."}}'),
('00000000-0000-0000-0000-000000000001', 'The Loyal Companion', 'A steadfast friend who will never abandon their allies, no matter the cost.', 'story', 'protagonist', 'Introduce to strengthen bonds between characters or show unwavering friendship.', '{"en":{"name":"The Loyal Companion","description":"A steadfast friend who will never abandon their allies, no matter the cost.","usage_examples":"Introduce to strengthen bonds between characters or show unwavering friendship."},"ru":{"name":"[RU] The Loyal Companion","description":"[RU] A steadfast friend who will never abandon their allies, no matter the cost.","usage_examples":"[RU] Introduce to strengthen bonds between characters or show unwavering friendship."},"ua":{"name":"[UA] The Loyal Companion","description":"[UA] A steadfast friend who will never abandon their allies, no matter the cost.","usage_examples":"[UA] Introduce to strengthen bonds between characters or show unwavering friendship."}}'),
('00000000-0000-0000-0000-000000000001', 'The Talking Animal', 'A beast with the gift of speech, offering wisdom, humor, or unexpected insight.', 'story', 'protagonist', 'Use to add whimsy or when nature itself needs a voice.', '{"en":{"name":"The Talking Animal","description":"A beast with the gift of speech, offering wisdom, humor, or unexpected insight.","usage_examples":"Use to add whimsy or when nature itself needs a voice."},"ru":{"name":"[RU] The Talking Animal","description":"[RU] A beast with the gift of speech, offering wisdom, humor, or unexpected insight.","usage_examples":"[RU] Use to add whimsy or when nature itself needs a voice."},"ua":{"name":"[UA] The Talking Animal","description":"[UA] A beast with the gift of speech, offering wisdom, humor, or unexpected insight.","usage_examples":"[UA] Use to add whimsy or when nature itself needs a voice."}}'),
('00000000-0000-0000-0000-000000000001', 'The Wise Mentor', 'An experienced guide who teaches and prepares the hero for their journey.', 'story', 'protagonist', 'Play when the hero needs guidance or when wisdom must be passed down.', '{"en":{"name":"The Wise Mentor","description":"An experienced guide who teaches and prepares the hero for their journey.","usage_examples":"Play when the hero needs guidance or when wisdom must be passed down."},"ru":{"name":"[RU] The Wise Mentor","description":"[RU] An experienced guide who teaches and prepares the hero for their journey.","usage_examples":"[RU] Play when the hero needs guidance or when wisdom must be passed down."},"ua":{"name":"[UA] The Wise Mentor","description":"[UA] An experienced guide who teaches and prepares the hero for their journey.","usage_examples":"[UA] Play when the hero needs guidance or when wisdom must be passed down."}}'),
('00000000-0000-0000-0000-000000000001', 'The Retired Knight', 'A warrior who hung up their sword, but may be called to fight once more.', 'story', 'protagonist', 'Introduce when experience is needed or to explore themes of aging and purpose.', '{"en":{"name":"The Retired Knight","description":"A warrior who hung up their sword, but may be called to fight once more.","usage_examples":"Introduce when experience is needed or to explore themes of aging and purpose."},"ru":{"name":"[RU] The Retired Knight","description":"[RU] A warrior who hung up their sword, but may be called to fight once more.","usage_examples":"[RU] Introduce when experience is needed or to explore themes of aging and purpose."},"ua":{"name":"[UA] The Retired Knight","description":"[UA] A warrior who hung up their sword, but may be called to fight once more.","usage_examples":"[UA] Introduce when experience is needed or to explore themes of aging and purpose."}}'),
('00000000-0000-0000-0000-000000000001', 'The Rebellious Heir', 'A successor who rejects tradition and forges their own path.', 'story', 'protagonist', 'Use when challenging authority or exploring generational conflict.', '{"en":{"name":"The Rebellious Heir","description":"A successor who rejects tradition and forges their own path.","usage_examples":"Use when challenging authority or exploring generational conflict."},"ru":{"name":"[RU] The Rebellious Heir","description":"[RU] A successor who rejects tradition and forges their own path.","usage_examples":"[RU] Use when challenging authority or exploring generational conflict."},"ua":{"name":"[UA] The Rebellious Heir","description":"[UA] A successor who rejects tradition and forges their own path.","usage_examples":"[UA] Use when challenging authority or exploring generational conflict."}}'),
('00000000-0000-0000-0000-000000000001', 'The Seer with No Eyes', 'A blind prophet who sees truths others cannot perceive.', 'story', 'protagonist', 'Play when prophecy or hidden knowledge becomes important.', '{"en":{"name":"The Seer with No Eyes","description":"A blind prophet who sees truths others cannot perceive.","usage_examples":"Play when prophecy or hidden knowledge becomes important."},"ru":{"name":"[RU] The Seer with No Eyes","description":"[RU] A blind prophet who sees truths others cannot perceive.","usage_examples":"[RU] Play when prophecy or hidden knowledge becomes important."},"ua":{"name":"[UA] The Seer with No Eyes","description":"[UA] A blind prophet who sees truths others cannot perceive.","usage_examples":"[UA] Play when prophecy or hidden knowledge becomes important."}}'),
('00000000-0000-0000-0000-000000000001', 'The Apprentice Mage', 'A young magic user still learning to control their growing powers.', 'story', 'protagonist', 'Introduce when magic goes awry or when potential must be nurtured.', '{"en":{"name":"The Apprentice Mage","description":"A young magic user still learning to control their growing powers.","usage_examples":"Introduce when magic goes awry or when potential must be nurtured."},"ru":{"name":"[RU] The Apprentice Mage","description":"[RU] A young magic user still learning to control their growing powers.","usage_examples":"[RU] Introduce when magic goes awry or when potential must be nurtured."},"ua":{"name":"[UA] The Apprentice Mage","description":"[UA] A young magic user still learning to control their growing powers.","usage_examples":"[UA] Introduce when magic goes awry or when potential must be nurtured."}}'),
('00000000-0000-0000-0000-000000000001', 'The Grizzled Mercenary', 'A battle-hardened soldier who fights for coin, but may find a cause worth dying for.', 'story', 'protagonist', 'Use to add cynicism that can transform into idealism.', '{"en":{"name":"The Grizzled Mercenary","description":"A battle-hardened soldier who fights for coin, but may find a cause worth dying for.","usage_examples":"Use to add cynicism that can transform into idealism."},"ru":{"name":"[RU] The Grizzled Mercenary","description":"[RU] A battle-hardened soldier who fights for coin, but may find a cause worth dying for.","usage_examples":"[RU] Use to add cynicism that can transform into idealism."},"ua":{"name":"[UA] The Grizzled Mercenary","description":"[UA] A battle-hardened soldier who fights for coin, but may find a cause worth dying for.","usage_examples":"[UA] Use to add cynicism that can transform into idealism."}}'),
('00000000-0000-0000-0000-000000000001', 'The Fool Who Knows Too Much', 'A jester or simpleton who speaks uncomfortable truths disguised as jokes.', 'story', 'protagonist', 'Play when truth needs to be spoken or when wisdom comes from unexpected sources.', '{"en":{"name":"The Fool Who Knows Too Much","description":"A jester or simpleton who speaks uncomfortable truths disguised as jokes.","usage_examples":"Play when truth needs to be spoken or when wisdom comes from unexpected sources."},"ru":{"name":"[RU] The Fool Who Knows Too Much","description":"[RU] A jester or simpleton who speaks uncomfortable truths disguised as jokes.","usage_examples":"[RU] Play when truth needs to be spoken or when wisdom comes from unexpected sources."},"ua":{"name":"[UA] The Fool Who Knows Too Much","description":"[UA] A jester or simpleton who speaks uncomfortable truths disguised as jokes.","usage_examples":"[UA] Play when truth needs to be spoken or when wisdom comes from unexpected sources."}}'),
('00000000-0000-0000-0000-000000000001', 'The Shape-shifting Ally', 'A friend who can change their form, hiding their true nature.', 'story', 'protagonist', 'Introduce to add mystery or when identity becomes fluid.', '{"en":{"name":"The Shape-shifting Ally","description":"A friend who can change their form, hiding their true nature.","usage_examples":"Introduce to add mystery or when identity becomes fluid."},"ru":{"name":"[RU] The Shape-shifting Ally","description":"[RU] A friend who can change their form, hiding their true nature.","usage_examples":"[RU] Introduce to add mystery or when identity becomes fluid."},"ua":{"name":"[UA] The Shape-shifting Ally","description":"[UA] A friend who can change their form, hiding their true nature.","usage_examples":"[UA] Introduce to add mystery or when identity becomes fluid."}}'),
('00000000-0000-0000-0000-000000000001', 'The Ghost of a Friend', 'A departed companion who returns to offer aid from beyond death.', 'story', 'protagonist', 'Use when the past haunts the present or when closure is needed.', '{"en":{"name":"The Ghost of a Friend","description":"A departed companion who returns to offer aid from beyond death.","usage_examples":"Use when the past haunts the present or when closure is needed."},"ru":{"name":"[RU] The Ghost of a Friend","description":"[RU] A departed companion who returns to offer aid from beyond death.","usage_examples":"[RU] Use when the past haunts the present or when closure is needed."},"ua":{"name":"[UA] The Ghost of a Friend","description":"[UA] A departed companion who returns to offer aid from beyond death.","usage_examples":"[UA] Use when the past haunts the present or when closure is needed."}}'),
('00000000-0000-0000-0000-000000000001', 'The Forgotten Twin', 'A sibling lost or hidden, whose return changes everything.', 'story', 'protagonist', 'Play to introduce shocking revelations or family drama.', '{"en":{"name":"The Forgotten Twin","description":"A sibling lost or hidden, whose return changes everything.","usage_examples":"Play to introduce shocking revelations or family drama."},"ru":{"name":"[RU] The Forgotten Twin","description":"[RU] A sibling lost or hidden, whose return changes everything.","usage_examples":"[RU] Play to introduce shocking revelations or family drama."},"ua":{"name":"[UA] The Forgotten Twin","description":"[UA] A sibling lost or hidden, whose return changes everything.","usage_examples":"[UA] Play to introduce shocking revelations or family drama."}}'),
('00000000-0000-0000-0000-000000000001', 'The Healer with a Secret', 'One who mends wounds but carries a hidden burden or dark knowledge.', 'story', 'protagonist', 'Introduce when healing is needed or when secrets must be revealed.', '{"en":{"name":"The Healer with a Secret","description":"One who mends wounds but carries a hidden burden or dark knowledge.","usage_examples":"Introduce when healing is needed or when secrets must be revealed."},"ru":{"name":"[RU] The Healer with a Secret","description":"[RU] One who mends wounds but carries a hidden burden or dark knowledge.","usage_examples":"[RU] Introduce when healing is needed or when secrets must be revealed."},"ua":{"name":"[UA] The Healer with a Secret","description":"[UA] One who mends wounds but carries a hidden burden or dark knowledge.","usage_examples":"[UA] Introduce when healing is needed or when secrets must be revealed."}}'),
('00000000-0000-0000-0000-000000000001', 'The Bard Who Can''t Lie', 'A storyteller cursed or blessed to speak only truth through song.', 'story', 'protagonist', 'Use when truth must be revealed or when music drives the narrative.', '{"en":{"name":"The Bard Who Can''t Lie","description":"A storyteller cursed or blessed to speak only truth through song.","usage_examples":"Use when truth must be revealed or when music drives the narrative."},"ru":{"name":"[RU] The Bard Who Can''t Lie","description":"[RU] A storyteller cursed or blessed to speak only truth through song.","usage_examples":"[RU] Use when truth must be revealed or when music drives the narrative."},"ua":{"name":"[UA] The Bard Who Can''t Lie","description":"[UA] A storyteller cursed or blessed to speak only truth through song.","usage_examples":"[UA] Use when truth must be revealed or when music drives the narrative."}}'),
('00000000-0000-0000-0000-000000000001', 'The Last of Their Kind', 'The final survivor of a lost people, carrying their legacy alone.', 'story', 'protagonist', 'Play to explore themes of extinction, preservation, and loneliness.', '{"en":{"name":"The Last of Their Kind","description":"The final survivor of a lost people, carrying their legacy alone.","usage_examples":"Play to explore themes of extinction, preservation, and loneliness."},"ru":{"name":"[RU] The Last of Their Kind","description":"[RU] The final survivor of a lost people, carrying their legacy alone.","usage_examples":"[RU] Play to explore themes of extinction, preservation, and loneliness."},"ua":{"name":"[UA] The Last of Their Kind","description":"[UA] The final survivor of a lost people, carrying their legacy alone.","usage_examples":"[UA] Play to explore themes of extinction, preservation, and loneliness."}}'),
('00000000-0000-0000-0000-000000000001', 'The Child of Prophecy', 'A young one foretold to bring great change, for good or ill.', 'story', 'protagonist', 'Introduce when destiny and innocence collide.', '{"en":{"name":"The Child of Prophecy","description":"A young one foretold to bring great change, for good or ill.","usage_examples":"Introduce when destiny and innocence collide."},"ru":{"name":"[RU] The Child of Prophecy","description":"[RU] A young one foretold to bring great change, for good or ill.","usage_examples":"[RU] Introduce when destiny and innocence collide."},"ua":{"name":"[UA] The Child of Prophecy","description":"[UA] A young one foretold to bring great change, for good or ill.","usage_examples":"[UA] Introduce when destiny and innocence collide."}}'),
('00000000-0000-0000-0000-000000000001', 'The Time-Lost Stranger', 'Someone displaced from their era, struggling to understand a changed world.', 'story', 'protagonist', 'Use when exploring themes of change, nostalgia, or fish-out-of-water scenarios.', '{"en":{"name":"The Time-Lost Stranger","description":"Someone displaced from their era, struggling to understand a changed world.","usage_examples":"Use when exploring themes of change, nostalgia, or fish-out-of-water scenarios."},"ru":{"name":"[RU] The Time-Lost Stranger","description":"[RU] Someone displaced from their era, struggling to understand a changed world.","usage_examples":"[RU] Use when exploring themes of change, nostalgia, or fish-out-of-water scenarios."},"ua":{"name":"[UA] The Time-Lost Stranger","description":"[UA] Someone displaced from their era, struggling to understand a changed world.","usage_examples":"[UA] Use when exploring themes of change, nostalgia, or fish-out-of-water scenarios."}}'),
('00000000-0000-0000-0000-000000000001', 'The Inventor of Impossible Things', 'A creator who defies the laws of nature with their ingenious devices.', 'story', 'protagonist', 'Play when innovation is needed or when science meets magic.', '{"en":{"name":"The Inventor of Impossible Things","description":"A creator who defies the laws of nature with their ingenious devices.","usage_examples":"Play when innovation is needed or when science meets magic."},"ru":{"name":"[RU] The Inventor of Impossible Things","description":"[RU] A creator who defies the laws of nature with their ingenious devices.","usage_examples":"[RU] Play when innovation is needed or when science meets magic."},"ua":{"name":"[UA] The Inventor of Impossible Things","description":"[UA] A creator who defies the laws of nature with their ingenious devices.","usage_examples":"[UA] Play when innovation is needed or when science meets magic."}}'),
('00000000-0000-0000-0000-000000000001', 'The One Who Remembers', 'A keeper of memories in a world that has forgotten its past.', 'story', 'protagonist', 'Introduce when history is important or when the past must be reclaimed.', '{"en":{"name":"The One Who Remembers","description":"A keeper of memories in a world that has forgotten its past.","usage_examples":"Introduce when history is important or when the past must be reclaimed."},"ru":{"name":"[RU] The One Who Remembers","description":"[RU] A keeper of memories in a world that has forgotten its past.","usage_examples":"[RU] Introduce when history is important or when the past must be reclaimed."},"ua":{"name":"[UA] The One Who Remembers","description":"[UA] A keeper of memories in a world that has forgotten its past.","usage_examples":"[UA] Introduce when history is important or when the past must be reclaimed."}}'),
('00000000-0000-0000-0000-000000000001', 'The Peacemaker', 'One who seeks harmony and understanding between warring factions.', 'story', 'protagonist', 'Use when conflict needs resolution or when diplomacy is the answer.', '{"en":{"name":"The Peacemaker","description":"One who seeks harmony and understanding between warring factions.","usage_examples":"Use when conflict needs resolution or when diplomacy is the answer."},"ru":{"name":"[RU] The Peacemaker","description":"[RU] One who seeks harmony and understanding between warring factions.","usage_examples":"[RU] Use when conflict needs resolution or when diplomacy is the answer."},"ua":{"name":"[UA] The Peacemaker","description":"[UA] One who seeks harmony and understanding between warring factions.","usage_examples":"[UA] Use when conflict needs resolution or when diplomacy is the answer."}}'),
('00000000-0000-0000-0000-000000000001', 'The Reluctant Leader', 'Someone thrust into command who doubts their ability to lead.', 'story', 'protagonist', 'Play when leadership is needed but confidence is lacking.', '{"en":{"name":"The Reluctant Leader","description":"Someone thrust into command who doubts their ability to lead.","usage_examples":"Play when leadership is needed but confidence is lacking."},"ru":{"name":"[RU] The Reluctant Leader","description":"[RU] Someone thrust into command who doubts their ability to lead.","usage_examples":"[RU] Play when leadership is needed but confidence is lacking."},"ua":{"name":"[UA] The Reluctant Leader","description":"[UA] Someone thrust into command who doubts their ability to lead.","usage_examples":"[UA] Play when leadership is needed but confidence is lacking."}}'),
('00000000-0000-0000-0000-000000000001', 'The Dreamer Who Dared', 'A visionary who pursues impossible dreams against all odds.', 'story', 'protagonist', 'Introduce when hope and ambition drive the story forward.', '{"en":{"name":"The Dreamer Who Dared","description":"A visionary who pursues impossible dreams against all odds.","usage_examples":"Introduce when hope and ambition drive the story forward."},"ru":{"name":"[RU] The Dreamer Who Dared","description":"[RU] A visionary who pursues impossible dreams against all odds.","usage_examples":"[RU] Introduce when hope and ambition drive the story forward."},"ua":{"name":"[UA] The Dreamer Who Dared","description":"[UA] A visionary who pursues impossible dreams against all odds.","usage_examples":"[UA] Introduce when hope and ambition drive the story forward."}}');
